import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BxGh02fV.js";const g=JSON.parse('{"title":"Objectives and milestones","description":"","frontmatter":{"title":"Objectives and milestones"},"headers":[],"relativePath":"en/guide/objectifs.md","filePath":"en/guide/objectifs.md"}'),s={name:"en/guide/objectifs.md"};function r(i,e,d,l,h,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="objectives-and-milestones" tabindex="-1">Objectives and milestones <a class="header-anchor" href="#objectives-and-milestones" aria-label="Permalink to &quot;Objectives and milestones&quot;">​</a></h1><p>This screen tracks what you want to deliver: your objectives, the milestones along the way, and the deliverables expected at each milestone. You come here to see at a glance what is done, what is missing, and to say yourself &quot;this is good&quot;.</p><p>The <strong>Objectives &amp; milestones</strong> entry (<strong>Steering</strong> group of the sidebar) only appears if the project has a steering register, or if its project model provides for deliverables. A software project with no objective does not see it.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>From top to bottom:</p><ul><li><strong>Review pending</strong>: when the agent team has stopped to ask for your opinion, a panel at the top says how often the review is scheduled (at each task, at each step, at each milestone; “step” takes the name your project model gives to a story) and lists the deliverables to review, with <strong>Accept</strong> and <strong>Refuse</strong>. A refusal requires a note, which goes back to the analyst.</li><li><strong>The work tree</strong>: each <strong>objective</strong> holds its <strong>milestones</strong>, and each milestone its <strong>deliverables</strong>. <ul><li>A <strong>milestone</strong> shows its due date, its state (<strong>upcoming</strong>, <strong>in progress</strong>, <strong>reached</strong>), its rate, and the effort spent against the estimate.</li><li>A <strong>deliverable</strong> shows its completeness rate, a coloured dot, what it still lacks and its review state.</li></ul></li><li><strong>No objective</strong> and <strong>No milestone</strong>: whatever is attached to nothing stays visible, in these two groups.</li><li><strong>Resources</strong>: the people or means doing the work.</li></ul><p>The rate says what is <strong>present</strong> against what is planned. It does not judge quality: only your review says a deliverable is done.</p><h3 id="the-colours" tabindex="-1">The colours <a class="header-anchor" href="#the-colours" aria-label="Permalink to &quot;The colours&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dot</th><th>Meaning</th></tr></thead><tbody><tr><td>Grey</td><td>not analysed yet</td></tr><tr><td>Red</td><td>under 50%</td></tr><tr><td>Orange</td><td>50 to 99%</td></tr><tr><td>Accent colour</td><td>100%, not reviewed yet</td></tr><tr><td>Green</td><td>100% and review accepted</td></tr></tbody></table><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="review-a-deliverable" tabindex="-1">Review a deliverable <a class="header-anchor" href="#review-a-deliverable" aria-label="Permalink to &quot;Review a deliverable&quot;">​</a></h3><p>When a deliverable has a completeness report, it carries its own <strong>Accept</strong> and <strong>Refuse</strong> buttons (a refusal requires a note). Your gesture is recorded as coming from the screen, and it goes through whatever the agents&#39; working mode: you are the one deciding.</p><p>If the agent team is waiting for your review of that very deliverable, its buttons are in the top panel: one decision per deliverable. Decide there, or ask the agent to relay your answer. While the team is waiting, that deliverable cannot be reviewed separately.</p><h3 id="the-dashboard-attention-point" tabindex="-1">The dashboard attention point <a class="header-anchor" href="#the-dashboard-attention-point" aria-label="Permalink to &quot;The dashboard attention point&quot;">​</a></h3><p>When a review is waiting for you, the <a href="/Effortless/en/guide/dashboard.html">Dashboard</a> shows a <strong>To review</strong> section, with the deliverables waiting (or <strong>Review awaited</strong> followed by the schedule, for example &quot;Review awaited (at each milestone)&quot;); a click opens this screen.</p><h3 id="link-the-map-to-deliverables" tabindex="-1">Link the Map to deliverables <a class="header-anchor" href="#link-the-map-to-deliverables" aria-label="Permalink to &quot;Link the Map to deliverables&quot;">​</a></h3><p>In the <a href="/Effortless/en/guide/ontologie.html">Map</a>, a solution, component or module atom can cite a deliverable: the <strong>Register deliverable</strong> field of the panel. The element then shows, on the Map, a coloured dot with the percentage.</p><h2 id="surfaces-hidden-by-the-model" tabindex="-1">Surfaces hidden by the model <a class="header-anchor" href="#surfaces-hidden-by-the-model" aria-label="Permalink to &quot;Surfaces hidden by the model&quot;">​</a></h2><p>A project model can hide what makes no sense for it. The <code>gestion-de-projet</code> model hides <strong>Drift</strong>, <strong>Git</strong>, <strong>Modules</strong> and the Git tile of the dashboard. These surfaces are <strong>absent</strong>, not greyed out. A hidden view reached anyway (a restored tab, for example) falls back to the Dashboard, and an attention point that would lead to a hidden view is not shown.</p><h2 id="budget-pro-edition" tabindex="-1">Budget (Pro edition) <a class="header-anchor" href="#budget-pro-edition" aria-label="Permalink to &quot;Budget (Pro edition)&quot;">​</a></h2><blockquote><p><strong>Pro.</strong> The budget only exists in the Pro edition.</p></blockquote><p>Under the resources, a <strong>Budget</strong> panel tracks the money. Amounts are entered in euros (the project currency, <code>EUR</code> by default) and stored in cents.</p><ul><li><strong>Posts</strong>: a planned amount, the spent amount and the gap (computed on expenses only).</li><li><strong>Expenses</strong>: a list, with add and remove.</li><li><strong>Labour</strong>: per resource, the minutes spent multiplied by the hourly rate. Minutes of a resource with no rate are counted apart, &quot;unpriced&quot;.</li><li><strong>Totals</strong>: planned, expenses, labour and global gap (planned minus expenses and labour).</li></ul><p>Resources also gain a kind (team, provider) and an hourly rate, also Pro. They are not entered on screen: ask the agent to set them, for example &quot;Set Camille Martin at €60 an hour&quot; or &quot;The print shop is a provider&quot;. As long as no resource has a rate, the panel reminds you.</p><p>Fictitious example: post &quot;Printing of the handouts&quot;, planned 1,200 EUR, one expense of 450 EUR; a resource &quot;Camille Martin&quot; at 60 EUR/h with 5 h spent adds 300 EUR of labour; the global gap is 450 EUR.</p><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>The agent reads and maintains the register; see <a href="/Effortless/en/agent/piloter.html#objectives-milestones-and-deliverables">Run the work</a> and <a href="/Effortless/en/agent/boucle-equipe.html">The team loop</a>. The review can be decided on screen or through the agent.</p>',27)])])}const p=t(s,[["render",r]]);export{g as __pageData,p as default};
